<?php
require dirname(__DIR__).'/app/bootstrap.php'; require_admin();
$error=''; $draft=null;
try {
 if ($_SERVER['REQUEST_METHOD']==='POST') {
  check_csrf(); $action=(string)($_POST['action'] ?? '');
  if ($action==='logout') { $_SESSION=[]; session_destroy(); header('Location: login.php'); exit; }
  if ($action==='save') {
   $draft=['id'=>(int)($_POST['id'] ?? 0),'name'=>trim((string)($_POST['name'] ?? '')),'description'=>trim((string)($_POST['description'] ?? '')),'url'=>trim((string)($_POST['url'] ?? '')),'icon'=>(string)($_POST['icon'] ?? ''),'category'=>(string)($_POST['category'] ?? ''),'color'=>(string)($_POST['color'] ?? ''),'sort_order'=>(int)($_POST['sort_order'] ?? 0),'active'=>isset($_POST['active'])?1:0,'featured'=>0,'icon_mode'=>(string)($_POST['icon_mode'] ?? 'favicon')];
   if ($draft['name']==='' || mb_strlen($draft['name'])>150 || mb_strlen($draft['description'])>255) $error='กรุณาระบุชื่อไม่เกิน 150 ตัวอักษร และรายละเอียดไม่เกิน 255 ตัวอักษร';
   elseif ($draft['url']!=='' && (!valid_url($draft['url']) || strlen($draft['url'])>2048)) $error='URL ต้องขึ้นต้นด้วย http:// หรือ https:// และยาวไม่เกิน 2,048 ตัวอักษร';
   elseif (!in_array($draft['icon_mode'],['favicon','icon'],true)) $error='รูปแบบไอคอนไม่ถูกต้อง';
   elseif (!isset(categories()[$draft['category']]) || !in_array($draft['icon'],icons(),true) || !preg_match('/^#[0-9a-fA-F]{6}$/',$draft['color'])) $error='หมวดหมู่ ไอคอน หรือสีไม่ถูกต้อง';
   else {
    $values=[$draft['name'],$draft['description'],$draft['url']?:null,$draft['icon'],$draft['category'],$draft['color'],$draft['sort_order'],$draft['active']];
    db()->beginTransaction();
    if ($draft['id']) { $stmt=db()->prepare('UPDATE systems SET name=?,description=?,url=?,icon=?,category=?,color=?,sort_order=?,active=? WHERE id=?'); $stmt->execute([...$values,$draft['id']]); }
    else { $stmt=db()->prepare('INSERT INTO systems(name,description,url,icon,category,color,sort_order,active) VALUES (?,?,?,?,?,?,?,?)'); $stmt->execute($values); }
    $savedId=$draft['id'] ?: (int)db()->lastInsertId();
    $stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'); $stmt->execute(['system_icon_'.$savedId,$draft['icon_mode']]); db()->commit();
   }
  } elseif ($action==='delete') { $id=(int)($_POST['id'] ?? 0); db()->beginTransaction(); $stmt=db()->prepare('DELETE FROM systems WHERE id=?'); $stmt->execute([$id]); $stmt=db()->prepare('DELETE FROM settings WHERE setting_key=?'); $stmt->execute(['system_icon_'.$id]); db()->commit(); }
  elseif ($action==='settings') {
   $public=trim((string)($_POST['public_url'] ?? '')); $contact=trim((string)($_POST['contact'] ?? '')); $notice=trim((string)($_POST['notice'] ?? ''));
   if ($public!=='' && (!valid_url($public) || parse_url($public,PHP_URL_SCHEME)!=='https' || strlen($public)>2048 || parse_url($public,PHP_URL_FRAGMENT) || parse_url($public,PHP_URL_QUERY))) $error='กรุณาใช้ URL สาธารณะแบบ https:// โดยไม่มี query หรือ #';
   elseif(mb_strlen($contact)>2000 || mb_strlen($notice)>2000) $error='ข้อความต้องไม่เกิน 2,000 ตัวอักษร';
   else { $stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'); db()->beginTransaction(); foreach(['public_url'=>$public,'contact'=>$contact,'notice'=>$notice] as $k=>$v) $stmt->execute([$k,$v]); db()->commit(); }
  } else $error='คำสั่งไม่ถูกต้อง';
  if (!$error) { $_SESSION['flash']='บันทึกเรียบร้อยแล้ว'; header('Location: index.php'.($action==='settings'?'#settings':($action==='password'?'#security':''))); exit; }
 }
 $systems=db()->query('SELECT * FROM systems ORDER BY sort_order,id')->fetchAll(); $settings=settings();
 $edit=$draft ?? ['id'=>0,'name'=>'','description'=>'','url'=>'','icon'=>'apps','category'=>'student','color'=>'#176b55','sort_order'=>count($systems)+1,'active'=>1];
 if (!$draft && isset($_GET['edit'])) { $stmt=db()->prepare('SELECT * FROM systems WHERE id=?'); $stmt->execute([(int)$_GET['edit']]); $found=$stmt->fetch(); if($found) $edit=$found; else $error='ไม่พบระบบที่ต้องการแก้ไข'; }
} catch(Throwable $err) { try { if(db()->inTransaction()) db()->rollBack(); } catch(Throwable $ignored) {} unavailable($err); }
$edit['icon_mode']=$edit['icon_mode'] ?? ($edit['id']?($settings['system_icon_'.$edit['id']] ?? 'favicon'):'favicon');
head('จัดการระบบ', 'admin-ui'); ?>
